/* The part a harness is compiled for (airoha_bmt_policy.h, generated by
 * platform/partitions.py). The pool is the one stock measures on a unit with
 * no factory-bad block among the top blocks it scans. */
#ifndef BMT_TEST_PART_H
#define BMT_TEST_PART_H
#include "airoha_bmt_policy.h"

#define PART_TOTAL BMT_TOTAL_BLOCKS
#define PART_POOL (PART_TOTAL * 8 / 100 > 250 ? 250u : PART_TOTAL * 8 / 100)
#define PART_SYS (PART_TOTAL - PART_POOL)
#define PART_PAGE BMT_PAGE_BYTES
#define PART_PAGES BMT_BLOCK_PAGES
#define PART_BLOCK (PART_PAGE * PART_PAGES)
#define PART_SPARE BMT_OOB_BYTES
#define PART_FREE BMT_OOB_FREE
#define PART_SECTIONS (PART_SPARE / 32)
/* The BMT checksum covers one 4-byte entry per pool block. */
#define PART_BMT_END (20 + 4 * PART_POOL)

/* A journal free-pool bitmap with every pool block free. */
static inline void part_all_free(unsigned char bits[32])
{
	for (unsigned i = 0; i < 32 * 8; i++) {
		if (i < PART_POOL) bits[i / 8] |= 1u << (i % 8);
		else bits[i / 8] &= ~(1u << (i % 8));
	}
}
#endif
